head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil54100n";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — loadTp, bzProcsNo

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil54100n.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_doSave", fn: function(){ return ((String(((dma_result.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "result.listProcsStatCd"); })())) == null ? '' : ((dma_result.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "result.listProcsStatCd"); })()))).length === 0)||(dma_result.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "result.listProcsStatCd"); })())==='30'||(dma_result.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "result.listProcsStatCd"); })())==='35'||(dma_result.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "result.listProcsStatCd"); })())==='37'); } }, { id: "btn_doSave", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '0'||(dma_pageContext.get("loadTp") ?? "") === '2' || (dma_pageContext.get("loadTp") ?? "") === '3'); } }, { id: "btn_goEditForm", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        form = (document.clmSchdlNotiForm || { elements: [] });
        loadTp = 'null';
        await scwin.checkSave();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54100n.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil54100n' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name divSearchBtn_cell_onclick
 * @description divSearchBtn_cell 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.divSearchBtn_cell_onclick = async function(e){
    try {
        await scwin.openComInfo4fee()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54100n.divSearchBtn_cell_onclick' }); }
};

/**
 * @method
 * @name rd_listFeeAnulfeeTpCd_onclick
 * @description rd_listFeeAnulfeeTpCd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_listFeeAnulfeeTpCd_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        scwin.feeChange(event)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil54100n.rd_listFeeAnulfeeTpCd_onclick' }); }
};

/**
 * @method
 * @name ipt_listCap_onkeyup
 * @description ipt_listCap 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_listCap_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil54100n.ipt_listCap_onkeyup' }); }
};

/**
 * @method
 * @name ipt_payAmt_onkeyup
 * @description ipt_payAmt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_payAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil54100n.ipt_payAmt_onkeyup' }); }
};

/**
 * @method
 * @name btn_doSave_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_doSave_onclick = async function(e){
    try {
        await scwin.doSave()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54100n.btn_doSave_onclick' }); }
};

/**
 * @method
 * @name btn_goEditForm_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goEditForm_onclick = function(e){
    try {
        scwin.goEditForm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil54100n.btn_goEditForm_onclick' }); }
};

/**
 * @method
 * @name btn_viewList_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_viewList_onclick = async function(e){
    try {
        await scwin.viewList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54100n.btn_viewList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_doSave
 * @description do Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_doSave = async function () {
    const sbmOptions = {
        id: "tx_doSave",
        method: "post",
        action: "/listInvstg/listFee.do",
        ref: "dma_doSaveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_viewList
 * @description view List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewList = async function () {
    const sbmOptions = {
        id: "tx_viewList",
        method: "post",
        action: "/listInvstg/listFee.do",
        ref: "dma_viewListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const bzProcsNo = 'null';
    if (loadTp === '2') {
        if (bzProcsNo === 'null') {
            await $c.win.alert('오류발생' + bzProcsNo);
        } else {
            if (bzProcsNo.length > 1) {
                await $c.win.alert('저장되었습니다.');
            }
        }
    }
    if (loadTp !== '0') {
        scwin.setDataVars();
        scwin.setData();
    }
};

/**
 * @method
 * @name setData
 * @description set Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setData = function () {
    /* empty */
};

/**
 * @method
 * @name feeChange
 * @description fee Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.feeChange = function () {
    $c.util.getComponent("ipt_isurCd").setValue("");
    $c.util.getComponent("ipt_comNm").setValue("");
    $c.util.getComponent("ipt_payAmt").setValue("");
};

/**
 * @method
 * @name setDataVars
 * @description set Data Vars 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataVars = function () {
    if (loadTp !== 0) {
        if (loadTp === '1') {
            scwin.setDisable();
        } else {
            const div = $c.util.getComponent('txt_divSearchBtn');
            div.innerHTML = '';
            $c.util.getComponent('rd_listFeeAnulfeeTpCd').setItemDisabled(0, !!(true));
            $c.util.getComponent('rd_listFeeAnulfeeTpCd').setItemDisabled(1, !!(true));
        }
    }
};

/**
 * @method
 * @name setDisable
 * @description set Disable 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDisable = function () {
    for (let i = 0; i < form.length; i++) {
        if (form[i].name !== 'method') {
            form[i].disabled = true;
        }
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} comNm comNm
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} mktNm mktNm
 * @param {String} typeNm typeNm
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, comNm, bzProcsNo, mktNm, typeNm) {
    $c.util.getComponent("ipt_isurCd").setValue(isurCd);
    $c.util.getComponent("ipt_comNm").setValue(comNm);
    $c.util.getComponent('dma_doSaveReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent("ipt_mktNm").setValue(mktNm);
    $c.util.getComponent("ipt_typeNm").setValue(typeNm);
    if (loadTp === '0' && ($c.util.getComponent('rd_listFeeAnulfeeTpCd').getValue() === '0004120101') === true) {
        if (mktNm === '코스닥시장') {
            $c.util.getComponent("ipt_payAmt").setValue('1,000,000');
        } else {
            $c.util.getComponent("ipt_payAmt").setValue('5,000,000');
        }
    }
};

/**
 * @method
 * @name goEditForm
 * @description go Edit Form 처리
 * @returns {void}
 * @hidden N
 */
scwin.goEditForm = function () {
    $c.util.getComponent('dma_doSaveReq').set('bzProcsNo', String(((dma_pageContext.get("bzProcsNo") ?? "")) == null ? '' : ((dma_pageContext.get("bzProcsNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("bzProcsNo") ?? "")) == null ? '' : ((dma_pageContext.get("bzProcsNo") ?? ""))));
    form.submit();
};

/**
 * @method
 * @name doSave
 * @description do Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doSave = async function () {
    form.action = '/listInvstg/listFee.do';
    let msg = '저장하시겠습니까?';
    if (loadTp === '2' || loadTp === '3') {
        msg = '수정하시겠습니까?';
        $c.util.getComponent('dma_doSaveReq').set('method', 'editFeeInfo');
    } else {
        $c.util.getComponent('dma_doSaveReq').set('method', 'saveFeeInfo');
    }
    if (await scwin.checkValue()) {
        if (await $c.win.confirm(msg)) {
            $c.util.getComponent('rd_listFeeAnulfeeTpCd').setItemDisabled(0, !!(false));
            $c.util.getComponent('rd_listFeeAnulfeeTpCd').setItemDisabled(1, !!(false));
            await scwin.tx_doSave();
        }
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    if (($c.util.getComponent('ipt_isurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_isurCd').getValue())) === '') {
        await $c.win.alert('법인을 선택하세요');
        return false;
    }
    if (($c.util.getComponent('ipt_payAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_payAmt').getValue())) === '') {
        await $c.win.alert('수수료를 입력하세요');
        return false;
    }
    if (($c.util.getComponent('ipt_listCap').getValue() == null ? '' : String($c.util.getComponent('ipt_listCap').getValue())) === '') {
        await $c.win.alert('상장자본금을 입력하세요');
        return false;
    }
    return true;
};

/**
 * @method
 * @name viewList
 * @description view List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewList = async function () {
    form.action = '/listInvstg/listFee.do';
    $c.util.getComponent('dma_doSaveReq').set('method', 'getFeeList');
    await scwin.tx_viewList();
};

/**
 * @method
 * @name openComInfo4fee
 * @description open Com Info4fee 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openComInfo4fee = async function () {
    const obj = $c.util.getComponent('rd_listFeeAnulfeeTpCd');
    let feeTp = '';
    const userId = $c.util.getComponent('dma_doSaveReq').get('regId');
    feeTp = obj.getValue();
    if (feeTp !== '') {
        findComInfo4fee(feeTp, userId);
    } else {
        await $c.win.alert('수수료 종류를 선택하세요.');
    }
};
